def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    if start == goal:
        if grid[start[0]][start[1]] == '.':
            return [start]
        else:
            return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]
    import heapq
    heap = []
    start_priority = abs(start[0] - goal[0]) + abs(start[1] - goal[1])
    heapq.heappush(heap, (start_priority, start))
    came_from = {}
    visited = set()
    while heap:
        current = heapq.heappop(heap)
        current_pos = current[1]
        if current_pos == goal:
            path = [current_pos]
            while current_pos in came_from:
                current_pos = came_from[current_pos]
                path.append(current_pos)
            return path[::-1]
        visited.add(current_pos)
        for dx, dy in directions:
            nx, ny = current_pos[0] + dx, current_pos[1] + dy
            next_pos = (nx, ny)
            if (0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == '.' and next_pos not in visited):
                priority = abs(nx - goal[0]) + abs(ny - goal[1])
                heapq.heappush(heap, (priority, next_pos))
                came_from[next_pos] = current_pos
    return []

