import heapq

def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    if start == goal:
        return [start] if grid[start[0]][start[1]] == '.' else []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    priority_queue = [(heuristic(start, goal), 0, start, [start])]
    heapq.heapify(priority_queue)
    visited = set()

    while priority_queue:
        f, g, current, path = heapq.heappop(priority_queue)
        if current == goal:
            return path
        if current in visited:
            continue
        visited.add(current)
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        for dr, dc in directions:
            next_r, next_c = current[0] + dr, current[1] + dc
            next_pos = (next_r, next_c)
            if 0 <= next_r < rows and 0 <= next_c < cols:
                if grid[next_r][next_c] != '#':
                    new_g = g + 1
                    h = heuristic(next_pos, goal)
                    new_f = new_g + h
                    heapq.heappush(priority_queue, (new_f, new_g, next_pos, path + [next_pos]))
    return []

