def solve(grid, start, goal):
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])
    s_r, s_c = start
    g_r, g_c = goal
    if not (0 <= s_r < rows and 0 <= s_c < cols) or not (0 <= g_r < rows and 0 <= g_c < cols):
        return []
    if grid[s_r][s_c] == '#' or grid[g_r][g_c] == '#':
        return []
    if start == goal:
        return [start]
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    import heapq
    hq = []
    heapq.heappush(hq, (0, start))
    distances = {start: 0}
    predecessors = {}
    found = False
    while hq:
        current_distance, current_pos = heapq.heappop(hq)
        if current_distance > distances.get(current_pos, 0):
            continue
        if current_pos == goal:
            found = True
            break
        current_r, current_c = current_pos
        for dr, dc in directions:
            new_r, new_c = current_r + dr, current_c + dc
            if 0 <= new_r < rows and 0 <= new_c < cols and grid[new_r][new_c] == '.':
                new_pos = (new_r, new_c)
                new_distance = current_distance + 1
                if new_pos not in distances or new_distance < distances[new_pos]:
                    distances[new_pos] = new_distance
                    predecessors[new_pos] = current_pos
                    heapq.heappush(hq, (new_distance, new_pos))
    if found:
        path = []
        current = goal
        while current is not None:
            path.append(current)
            current = predecessors.get(current, None)
        return path[::-1]
    else:
        return []

