def solve(grid, start, goal):
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols

    if not is_valid(*start) or not is_valid(*goal):
        return []
    if start == goal:
        return [start]
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]
    path = [start]
    visited = set()
    visited.add((start[0], start[1]))

    while path:
        current = path[-1]
        if current == goal:
            return path
        possible_next = []
        for dx, dy in directions:
            nx, ny = current[0] + dx, current[1] + dy
            if is_valid(nx, ny) and grid[nx][ny] == '.' and (nx, ny) not in visited:
                possible_next.append((nx, ny))
        if not possible_next:
            visited.remove((current[0], current[1]))
            path.pop()
        else:
            possible_next.sort(key=lambda p: abs(p[0] - goal[0]) + abs(p[1] - goal[1]))
            next_cell = possible_next[0]
            path.append(next_cell)
            visited.add((next_cell[0], next_cell[1]))
    return []

