def solve(grid, start, goal):
    import heapq
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0]) if rows > 0 else 0

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols

    if not is_valid(*start) or not is_valid(*goal):
        return []

    def is_wall(r, c):
        return grid[r][c] == '#'

    if start == goal:
        if not is_wall(*start):
            return [start]
        else:
            return []

    if is_wall(*start) or is_wall(*goal):
        return []

    INF = float('inf')
    dist = [[INF] * cols for _ in range(rows)]
    pred = [[None] * cols for _ in range(rows)]
    dist[start[0]][start[1]] = 0
    heap = [(0, start[0], start[1])]
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    found = False

    while heap:
        d, r, c = heapq.heappop(heap)
        if (r, c) == goal:
            found = True
            break
        if d > dist[r][c]:
            continue
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc) and not is_wall(nr, nc):
                if dist[nr][nc] > d + 1:
                    dist[nr][nc] = d + 1
                    pred[nr][nc] = (r, c)
                    heapq.heappush(heap, (d + 1, nr, nc))

    if found:
        path = []
        current = goal
        while current is not None:
            path.append(current)
            current = pred[current[0]][current[1]]
        path.reverse()
        return path
    else:
        return []

