    if not grid:
        return []
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols
    start_row, start_col = start
    goal_row, goal_col = goal
    if (not is_valid(start_row, start_col)) or (not is_valid(goal_row, goal_col)):
        return []
    if grid[start_row][start_col] == '#' or grid[goal_row][goal_col] == '#':
        return []
    if start == goal:
        return [start]

    def heuristic(pos):
        return abs(pos[0] - goal_row) + abs(pos[1] - goal_col)

    heap = []
    heapq.heappush(heap, (heuristic(start), start))
    g_scores = { (r, c): float('inf') for r in range(rows) for c in range(cols) }
    g_scores[start] = 0
    came_from = {}
    visited = set()

    while heap:
        f, current = heapq.heappop(heap)
        if current in visited:
            continue
        visited.add(current)
        if current == goal:
            path = []
            curr = current
            while curr != start:
                path.append(curr)
                curr = came_from[curr]
            path.append(start)
            return path[::-1]
        current_row, current_col = current
        neighbors = [
            (current_row - 1, current_col),
            (current_row + 1, current_col),
            (current_row, current_col - 1),
            (current_row, current_col + 1)
        ]
        for neighbor in neighbors:
            n_r, n_c = neighbor
            if not is_valid(n_r, n_c) or grid[n_r][n_c] == '#':
                continue
            tentative_g = g_scores[current] + 1
            if tentative_g < g_scores[(n_r, n_c)]:
                g_scores[(n_r, n_c)] = tentative_g
                heapq.heappush(heap, (tentative_g + heuristic(neighbor), neighbor))
                came_from[(n_r, n_c)] = current
    return []

